"use strict";(self.webpackChunkdocs_appkeyid=self.webpackChunkdocs_appkeyid||[]).push([["1426"],{6588(e,n,t){t.r(n),t.d(n,{metadata:()=>a,default:()=>m,frontMatter:()=>c,contentTitle:()=>s,toc:()=>d,assets:()=>r});var a=JSON.parse('{"id":"concepts/attested-communication/why-acknowlegement","title":"Why Acknowledgements Matter","description":"Acknowledgements","source":"@site/docs/concepts/attested-communication/why-acknowlegement.mdx","sourceDirName":"concepts/attested-communication","slug":"/concepts/attested-communication/why-acknowlegement","permalink":"/AppKeyIdDocs/docs/concepts/attested-communication/why-acknowlegement","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"sidebar_position":3},"sidebar":"conceptsSidebar","previous":{"title":"What is a Card?","permalink":"/AppKeyIdDocs/docs/concepts/attested-communication/what-is-a-card"},"next":{"title":"Chain of Custody","permalink":"/AppKeyIdDocs/docs/concepts/attested-communication/chain-of-custody"}}'),i=t(4848),o=t(8453);let c={sidebar_position:3},s="Why Acknowledgements Matter",r={},d=[{value:"Cryptographically Verifiable",id:"cryptographically-verifiable",level:2},{value:"Two-Way Communication",id:"two-way-communication",level:2},{value:"Provides User Access Control to Communication",id:"provides-user-access-control-to-communication",level:2}];function l(e){let n={h1:"h1",h2:"h2",header:"header",img:"img",p:"p",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"why-acknowledgements-matter",children:"Why Acknowledgements Matter"})}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.img,{alt:"Acknowledgements",src:t(1949).A+"",width:"1536",height:"1024"})}),"\n",(0,i.jsx)(n.p,{children:"The foundation of attested communication is the acknowledgement. A message has little value if the\nsender cannot prove who actually received it, whether it was understood, or even whether it was\nopened by the intended recipient. Traditional communication systems\u2014including email, SMS,\ninstant messaging, and video conferencing\u2014provide only weak evidence. An email reply can be forged,\na messaging account can be compromised, and a video call participant can increasingly be imitated\nusing AI-generated voice and video. None of these systems provide strong cryptographic proof that\na specific individual acknowledged a specific communication."}),"\n",(0,i.jsx)(n.h2,{id:"cryptographically-verifiable",children:"Cryptographically Verifiable"}),"\n",(0,i.jsx)(n.p,{children:"AppKeyId changes this model by making acknowledgement a cryptographically verifiable event.\nTo acknowledge a Card, the recipient must authenticate using a FIDO2 passkey.\nIn most cases, this requires biometric verification such as Face ID, Touch ID, or the device\u2019s\nfingerprint or facial recognition system. The resulting digital signature proves that the\nacknowledgement originated from the recipient\u2019s registered passkey and not simply from\nsomeone who had access to an email account or messaging application."}),"\n",(0,i.jsx)(n.p,{children:"No authentication system is absolutely perfect. For example, a stolen hardware security key that\nis not PIN protected could theoretically be misused. However, such attacks are significantly more\ndifficult than compromising an email account or sending a fraudulent text message. The confidence\nprovided by passkey authentication is orders of magnitude higher than traditional communication\nmethods, making acknowledgements substantially more trustworthy."}),"\n",(0,i.jsx)(n.h2,{id:"two-way-communication",children:"Two-Way Communication"}),"\n",(0,i.jsx)(n.p,{children:"An acknowledgement is more than a receipt\u2014it establishes identity. Unlike scanning an anonymous\nrestaurant QR code, an AppKeyId acknowledgement identifies the verified user who consumed the\nCard. Because the user\u2019s identity is known, the acknowledgement itself becomes an authenticated\ntransaction that can carry useful application data. A single acknowledgement can simultaneously\nconfirm receipt while allowing the user to join a team, register attendance at an event, cast\na vote, approve a document, request access to a protected resource, or trigger any number of\nauthenticated business workflows. Communication becomes an action rather than simply the exchange\nof information."}),"\n",(0,i.jsx)(n.p,{children:"Acknowledgements also transform communication from a one-way broadcast into a two-way,\nauthenticated conversation. The sender no longer wonders whether the message reached the\nright person or whether the recipient actually acted upon it. Every acknowledgement\ncreates a verifiable chain of custody that records who acknowledged the Card, when they\nacknowledged it, and, if permitted by the user and application, where the acknowledgement\noccurred. This audit trail is invaluable for compliance, regulated industries, project management,\nlegal notifications, healthcare, education, and any workflow that depends on accountability."}),"\n",(0,i.jsx)(n.h2,{id:"provides-user-access-control-to-communication",children:"Provides User Access Control to Communication"}),"\n",(0,i.jsx)(n.p,{children:"Finally, acknowledgements enable precise control over who can consume information.\nBecause every recipient is authenticated before a Card is opened or acknowledged,\nAppKeyId can enforce distribution policies with cryptographic certainty. A Card can be\nlimited to a single individual, a defined team, members of a particular organization,\nor any other authorized audience. Unauthorized users simply cannot consume or acknowledge\nthe communication. This greatly reduces accidental disclosure, unauthorized forwarding,\nand information leakage while giving senders confidence that sensitive information remains\nwithin its intended audience."}),"\n",(0,i.jsx)(n.p,{children:"In the AI era, where convincing impersonation has become commonplace, delivery is no\nlonger enough. What matters is knowing who acknowledged the communication, when they\nacknowledged it, and having cryptographic proof that the acknowledgement can be trusted.\nThat is the foundation of Attested Communication."})]})}function m(e={}){let{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}},1949(e,n,t){t.d(n,{A:()=>a});let a=t.p+"assets/images/acknowledge-26777532563e08b4d3f6680eaa7449e1.png"},8453(e,n,t){t.d(n,{R:()=>c,x:()=>s});var a=t(6540);let i={},o=a.createContext(i);function c(e){let n=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:c(e.components),a.createElement(o.Provider,{value:n},e.children)}}}]);